      "gap_before": 0.0097,
      "gap_after": 0.0
    },
    {
      "claim_id": "C2",
      "knobs": {"RUN_TAG": "variable (shuffling seed)"},
      "evidence": "Same as C1 for balanced accuracy.",
      "gap_before": 0.0475,
      "gap_after": 0.0
    }
  ],
  "unexplained": []
}
EOF"}

